/*
 * A032842  Numbers whose base-4 representation Sum_{i=0..m} d(i)*4^i has d(m)
 *          < d(m-1) > d(m-2) < ...
 * https://oeis.org/A032842
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base
 * Formula:   a(n) = nth positive integer whose base‑4 digits alternate "<"
 *            then ">" then "<" …, starting with "<". The sequence is
 *            generated by counting and selecting the digits combinatorially
 * Range:     u8 n <= 31, u16 n <= 793, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>

/* Number of base‑4 digits that can appear in a 64‑bit value:
   4^32 > 2^64, so 64 digits are more than enough for the tested range.   */
#define MAX_LEN 64

static uint64_t dp[MAX_LEN][4][2];
static bool dp_initialized = false;

/* Precompute counts:
   dp[len][prev][need] = number of ways to fill len more digits
   after a digit 'prev' when the next comparison must be 'need':
   need==1  → next digit must be > prev
   need==0  → next digit must be < prev
 */
static void init_dp(void) {
    if (dp_initialized) return;
    for (int prev = 0; prev < 4; ++prev)
        for (int need = 0; need < 2; ++need)
            dp[0][prev][need] = 1;            /* no remaining digits */

    for (int len = 1; len < MAX_LEN; ++len) {
        for (int prev = 0; prev < 4; ++prev) {
            for (int need = 0; need < 2; ++need) {
                uint64_t sum = 0;
                if (need) {                     /* need greater */
                    for (int d = prev + 1; d <= 3; ++d)
                        sum += dp[len - 1][d][1 - need];
                } else {                        /* need smaller */
                    for (int d = 0; d < prev; ++d)
                        sum += dp[len - 1][d][1 - need];
                }
                dp[len][prev][need] = sum;
            }
        }
    }
    dp_initialized = true;
}

/* Return the nth term (1‑based) of A032842 */
seq_t a(idx_t n) {
    if (n == 0) return (seq_t)0;          /* undefined for n=0 */

    init_dp();

    idx_t rem = n;
    int len = 1;                           /* current number of digits */

    /* Determine the length of the desired term */
    while (1) {
        uint64_t count_len = 0;
        for (int d = 1; d <= 3; ++d)          /* the most significant digit cannot be 0 */
            count_len += dp[len - 1][d][1];    /* next digit must be greater than first */
        if (rem <= count_len) break;
        rem -= count_len;
        ++len;
    }

    seq_t value = 0;
    int prev_digit = 0;
    bool need_greater = true;              /* after first digit the next comparison is ">" */
    int rem_len = len - 1;                 /* digits still to be added */

    /* Pick the first (most significant) digit */
    for (int d = 1; d <= 3; ++d) {
        uint64_t cnt = dp[len - 1][d][1];
        if (rem > cnt) {
            rem -= cnt;
            continue;
        }
        value = value * (seq_t)4 + (seq_t)d;
        prev_digit = d;
        need_greater = true;
        break;
    }

    /* Construct the remaining digits from most to least significant */
    while (rem_len > 0) {
        for (int d = 0; d <= 3; ++d) {
            if (need_greater) {
                if (d <= prev_digit) continue;
            } else {
                if (d >= prev_digit) continue;
            }
            uint64_t cnt = dp[rem_len - 1][d][!need_greater];
            if (rem > cnt) {
                rem -= cnt;
                continue;
            }
            value = value * (seq_t)4 + (seq_t)d;
            prev_digit = d;
            need_greater = !need_greater;
            --rem_len;
            break;
        }
    }

    return value;
}
